<?php declare(strict_types=1); namespace Neok\Pay\Laravel;
use GuzzleHttp\Client as GuzzleClient; use GuzzleHttp\Psr7\HttpFactory; use Illuminate\Support\ServiceProvider; use Neok\Pay\{Client,ClientConfig}; use Neok\Pay\Laravel\Commands\{DoctorCommand,InstallCommand}; use Psr\Http\Client\ClientInterface; use Psr\Http\Message\{RequestFactoryInterface,StreamFactoryInterface};
final class NeokPayServiceProvider extends ServiceProvider { public function register():void{$this->mergeConfigFrom(__DIR__.'/../config/neokpay.php','neokpay');$this->app->singleton(ClientInterface::class,fn()=>new GuzzleClient);$this->app->singleton(HttpFactory::class,fn()=>new HttpFactory);$this->app->alias(HttpFactory::class,RequestFactoryInterface::class);$this->app->alias(HttpFactory::class,StreamFactoryInterface::class);$this->app->singleton(ClientConfig::class,fn()=>new ClientConfig((string)config('neokpay.api_key'),(string)config('neokpay.base_url')));$this->app->singleton(Client::class,fn($app)=>new Client($app->make(ClientConfig::class),$app->make(ClientInterface::class),$app->make(RequestFactoryInterface::class),$app->make(StreamFactoryInterface::class)));} public function boot():void{$this->publishes([__DIR__.'/../config/neokpay.php'=>config_path('neokpay.php')],'neokpay-config');$this->commands([InstallCommand::class,DoctorCommand::class]); if(config('neokpay.webhook.enabled'))$this->loadRoutesFrom(__DIR__.'/../routes/webhooks.php');} }
